const raw = $input.first().json ?? {};
const telemetry = raw.data && typeof raw.data === 'object' && !Array.isArray(raw.data) ? raw.data : {};
const policy = Object.freeze({ minFreePercent: 25, minDaysToFull: 30, maxRestoreAgeDays: 35 });
const reasons = [];
const now = Math.floor(Date.now() / 1000);
const createdEpoch = telemetry.createdEpoch;
const ageMinutes = Number.isSafeInteger(createdEpoch) ? Math.floor((now - createdEpoch) / 60) : null;
const completionFresh = ageMinutes !== null && ageMinutes >= 0 && ageMinutes <= 105;
if (!completionFresh) reasons.push('COMPLETION_STALE_OR_MISSING');
const integerFields = ['backupBytes', 'estimatedDatabaseBytes', 'growth7Bytes', 'growth30Bytes', 'targetTotalBytes', 'targetFreeBytes', 'projectedFreePercent', 'projectedDaysToFull', 'restoreAgeDays'];
const integersValid = integerFields.every((key) => typeof telemetry[key] === 'number' && Number.isSafeInteger(telemetry[key]));
const rangesValid = integersValid && telemetry.backupBytes >= 0 && telemetry.estimatedDatabaseBytes > 0 && telemetry.targetTotalBytes > 0 && telemetry.targetFreeBytes >= telemetry.estimatedDatabaseBytes && telemetry.targetFreeBytes <= telemetry.targetTotalBytes && telemetry.projectedFreePercent >= 0 && telemetry.projectedFreePercent <= 100 && telemetry.projectedDaysToFull >= -1 && telemetry.restoreAgeDays >= -1;
const safeFloorRatio = (value, multiplier, divisor) => {
  if (!Number.isSafeInteger(value) || !Number.isSafeInteger(divisor) || value < 0 || divisor <= 0) return null;
  const quotient = (BigInt(value) * BigInt(multiplier)) / BigInt(divisor);
  return quotient <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(quotient) : null;
};
const projectedFreeBytes = rangesValid ? telemetry.targetFreeBytes - telemetry.estimatedDatabaseBytes : null;
const expectedProjectedFreePercent = rangesValid ? safeFloorRatio(projectedFreeBytes, 100, telemetry.targetTotalBytes) : null;
const capacityConsistent = rangesValid && expectedProjectedFreePercent !== null && telemetry.projectedFreePercent === expectedProjectedFreePercent;
const growthStatusesValid = ['available', 'insufficient_history'].includes(telemetry.growth7Status) && ['available', 'insufficient_history'].includes(telemetry.growth30Status);
const growthValuesConsistent = integersValid && growthStatusesValid && (telemetry.growth7Status === 'available' || telemetry.growth7Bytes === 0) && (telemetry.growth30Status === 'available' || telemetry.growth30Bytes === 0);
const expectedDaysToFull = integersValid && telemetry.growth30Status === 'available' && telemetry.growth30Bytes > 0 ? safeFloorRatio(telemetry.targetFreeBytes, 30, telemetry.growth30Bytes) : -1;
const daysToFullConsistent = integersValid && expectedDaysToFull !== null && telemetry.projectedDaysToFull === expectedDaysToFull;
const telemetryValid = telemetry.schemaVersion === 'diis-backup-telemetry-v1' && Number.isSafeInteger(createdEpoch) && rangesValid && capacityConsistent && growthStatusesValid && growthValuesConsistent && daysToFullConsistent;
if (!telemetryValid) reasons.push('TELEMETRY_INVALID');
if (Number.isSafeInteger(telemetry.projectedFreePercent) && telemetry.projectedFreePercent < policy.minFreePercent) reasons.push('CAPACITY_LOW');
if (Number.isSafeInteger(telemetry.projectedDaysToFull) && telemetry.projectedDaysToFull >= 0 && telemetry.projectedDaysToFull < policy.minDaysToFull) reasons.push('DAYS_TO_FULL_LOW');
if (telemetry.offsiteStatus !== 'complete') reasons.push('OFFSITE_INCOMPLETE');
if (telemetry.restoreStatus !== 'success' || !Number.isSafeInteger(telemetry.restoreAgeDays) || telemetry.restoreAgeDays < 0 || telemetry.restoreAgeDays > policy.maxRestoreAgeDays) reasons.push('RESTORE_PROOF_MISSING_OR_STALE');
return [{ json: { completionFresh, ageMinutes, backupBytes: integersValid ? telemetry.backupBytes : 0, growth7Bytes: integersValid ? telemetry.growth7Bytes : 0, growth30Bytes: integersValid ? telemetry.growth30Bytes : 0, targetFreeBytes: integersValid ? telemetry.targetFreeBytes : 0, projectedFreePercent: integersValid ? telemetry.projectedFreePercent : 0, projectedDaysToFull: integersValid ? telemetry.projectedDaysToFull : -1, restoreStatus: String(telemetry.restoreStatus ?? 'missing'), restoreAgeDays: integersValid ? telemetry.restoreAgeDays : -1, notificationChannelType: 'smtp', notificationChannelReadiness: 'unbound', monitorFailure: false, reasonCodes: [...new Set(reasons)].sort(), alertRequired: reasons.length > 0 } }];
